/* @lc app=leetcode id=2492 lang=kotlin */ class Solution { fun minScore(n: Int, roads: Array<IntArray>): Int = roads.flatMap { (a, b, _) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> HashSet<Int>().also { it.add(1) }.let { seen -> generateSequence(listOf(1)) { f -> f.flatMap { g[it].orEmpty() }.filter { seen.add(it) }.takeIf { it.isNotEmpty() } }.count().let { roads.filter { it[0] in seen }.minOf { it[2] } } } } }